import { existsSync } from "node:fs";
import path from "node:path";
import Link from "next/link";
import type { AccountReport, CategoryReport } from "@/lib/finance-reports";
import { ACCOUNT_GROUPS, type AccountGroup } from "@/lib/finance";
import { change, money, num } from "@/lib/format";
import { AccountMark, accountLogoUrl } from "./AccountMark";
import { FinIcon, InfoTip, type FinIconName } from "./FinIcon";

// 3D icons generated by tools/finance-icons.sh into public/icons/fin. Until one exists, the line icon is used.
export type ArtName = "income" | "expense" | "transactions" | "net" | "accounts" | "partners" | "other" | "by-account" | "by-category" | "forecast";
const artCache = new Map<ArtName, boolean>();
const hasArt = (name: ArtName) => {
  if (!artCache.has(name)) artCache.set(name, existsSync(path.join(process.cwd(), "public", "icons", "fin", `${name}.png`)));
  return artCache.get(name)!;
};

/** The generated 3D icon when present, else the line icon. */
export function Art({ art, icon, size = 22 }: { art?: ArtName; icon: FinIconName; size?: number }) {
  // eslint-disable-next-line @next/next/no-img-element
  return art && hasArt(art) ? <img className="art" src={`/icons/fin/${art}.png`} alt="" width={size * 1.8} height={size * 1.8} /> : <FinIcon name={icon} size={size} />;
}

export type Tone = "green" | "amber" | "red" | "orange" | "blue" | "violet" | "navy";

const share = (part: number, total: number) => (total > 0 ? `${((part / total) * 100).toFixed(1)}%` : "0.0%");

// Categorical hues (validated palette), picked from the category itself so its color never changes with its rank.
const DOTS = ["#2a78d6", "#eb6834", "#1baf7a", "#eda100", "#e87ba4", "#008300", "#4a3aa7", "#e34948"];
const dotColor = (key: string) => DOTS[[...key].reduce((h, c) => (h * 31 + c.charCodeAt(0)) >>> 0, 7) % DOTS.length];

/**
 * One cell of a `.fstats` strip: a tone marker and label, the figure, and a caption. A logo sits in the top-right corner,
 * so cells with and without one keep their figures in line. `info` shows on hover; with `href` the whole cell links there.
 */
export function StatCard({ tone, logo, label, value, caption, info, href, note }: {
  tone: Tone; logo?: string | null; label: string; value: string; caption: React.ReactNode; info: string; href?: string;
  note?: string | null; // an extra line under the caption, e.g. how much of the figure is still pending
}) {
  return (
    <li className={`fstat fstat--${tone}${logo ? " fstat--logo" : ""}`} title={info}>
      <span className="fstat__label">
        <i className="fstat__mark" aria-hidden="true" />
        {href ? <Link href={href} className="stretched">{label}</Link> : label}
      </span>
      <strong className="fstat__value">{value}</strong>
      <small className="fstat__caption">{caption}</small>
      {note && <small className="fstat__note">{note}</small>}
      {/* eslint-disable-next-line @next/next/no-img-element */}
      {logo && <img className="fstat__logo" src={logo} alt="" width={36} height={36} />}
    </li>
  );
}

/** Section heading with an icon and a muted subtitle (e.g. the period). */
export function SectionTitle({ icon, art, title, sub, children, id }: { icon: FinIconName; art?: ArtName; title: string; sub?: string; children?: React.ReactNode; id?: string }) {
  return (
    <header className="fsection" id={id}>
      <span className="fsection__icon"><Art art={art} icon={icon} /></span>
      <h2>{title}</h2>
      {sub && <span className="fsection__sub">{sub}</span>}
      {children && <span className="fsection__end">{children}</span>}
    </header>
  );
}

/** Net result, then the period split by account and by category. */
export function FinanceSummary({
  periodLabel, income, expense, balance, extra, accounts, unassigned, incomeCats, expenseCats, qs,
}: {
  periodLabel: string;
  income: number;
  expense: number;
  balance: number;
  extra: { label: string; value: number } | null; // e.g. expected net at month end
  accounts: AccountReport[];
  unassigned: { income: number; expense: number; count: number };
  incomeCats: CategoryReport[];
  expenseCats: CategoryReport[];
  qs: string; // period query for links, e.g. "period=month"
}) {
  const net = income - expense;
  const volume = income + expense;
  const active = accounts.filter((a) => a.count > 0).sort((a, b) => b.income + b.expense - (a.income + a.expense));
  const cats = [
    ...incomeCats.map((c) => ({ ...c, type: "income" as const })),
    ...expenseCats.map((c) => ({ ...c, type: "expense" as const })),
  ].sort((a, b) => b.total - a.total);

  return (
    <section className="fsum">
      <div className="fsum__net">
        <span className="fsum__eyebrow">Net result</span>
        <strong className={`fsum__big ${net < 0 ? "neg" : "pos"}`}>{money(net)}</strong>
        <p className="muted">From booked transactions · {periodLabel}</p>
        <dl className="fsum__rows">
          <div><dt>Income</dt><dd className="pos">{money(income)}</dd></div>
          <div><dt>Expenses</dt><dd className="neg">− {money(expense)}</dd></div>
        </dl>
        <div className={`fsum__bar ${balance < 0 ? "fsum__bar--neg" : ""}`}>
          <span>Balance · all accounts</span>
          <strong>{money(balance)}</strong>
        </div>
        {extra && (
          <div className="fsum__extra">
            <span>{extra.label}</span>
            <strong>{money(extra.value)}</strong>
          </div>
        )}
      </div>

      <div className="fsum__col">
        <header className="fsum__head">
          <span className="fsum__icon"><Art art="by-account" icon="card" size={20} /></span>
          <h3>By account</h3>
          <InfoTip text="Money in (green) and out (red) of each virtual account in the period, its net, and its share of all movement." />
          <Link href="/finance/accounts" className="fsum__more" aria-label="All accounts"><FinIcon name="next" size={18} /></Link>
        </header>
        {active.length === 0 && unassigned.count === 0 ? (
          <p className="empty">No transactions in this period.</p>
        ) : (
          <ul className="flist">
            {active.map((a) => (
              <li key={a.id}>
                <AccountMark id={a.id} name={a.name} logo={a.logo} size={28} />
                <Link href={`/finance/transactions?account=${a.id}&${qs}`} className="flist__name">{a.name}</Link>
                <span className="flist__flow">
                  {a.income !== 0 && <span className="flist__in">In {money(a.income)}</span>}
                  {a.expense !== 0 && <span className="flist__out">Out {money(a.expense)}</span>}
                </span>
                <strong className={a.income - a.expense < 0 ? "neg" : undefined}>{money(a.income - a.expense)}</strong>
                <span className="flist__share">{share(a.income + a.expense, volume)}</span>
              </li>
            ))}
            {unassigned.count > 0 && (
              <li>
                <span className="flist__blank" aria-hidden="true">?</span>
                <Link href={`/finance/transactions?account=none&${qs}`} className="flist__name muted">No account</Link>
                <span className="flist__flow">
                  {unassigned.income !== 0 && <span className="flist__in">In {money(unassigned.income)}</span>}
                  {unassigned.expense !== 0 && <span className="flist__out">Out {money(unassigned.expense)}</span>}
                </span>
                <strong>{money(unassigned.income - unassigned.expense)}</strong>
                <span className="flist__share">{share(unassigned.income + unassigned.expense, volume)}</span>
              </li>
            )}
          </ul>
        )}
      </div>

      <div className="fsum__col">
        <header className="fsum__head">
          <span className="fsum__icon"><Art art="by-category" icon="tag" size={20} /></span>
          <h3>By category</h3>
          <InfoTip text="Each category's total in the period and its share of all money in and out. The arrow compares with the period just before." />
          <Link href={`/finance/reports?${qs}`} className="fsum__more" aria-label="Reports"><FinIcon name="next" size={18} /></Link>
        </header>
        {cats.length === 0 ? (
          <p className="empty">No transactions in this period.</p>
        ) : (
          <ul className="flist flist--cats">
            {cats.map((c) => {
              const d = change(c.total, c.previous);
              return (
                <li key={`${c.type}:${c.id ?? "none"}`}>
                  <i className="flist__dot" style={{ background: c.id ? dotColor(c.id) : "#9aa3b5" }} aria-hidden="true" />
                  {c.id ? (
                    <Link href={`/finance/transactions?category=${c.id}&${qs}`} className="flist__name">{c.name}</Link>
                  ) : (
                    <span className="flist__name muted">{c.name}</span>
                  )}
                  <span className="flist__delta" title={`Previous period: ${money(c.previous)}`}>{d ?? ""}</span>
                  <strong className={c.type === "income" ? "pos" : "neg"}>{c.type === "income" ? "" : "−"}{money(c.total)}</strong>
                  <span className="flist__share">{share(c.total, volume)}</span>
                </li>
              );
            })}
          </ul>
        )}
      </div>
    </section>
  );
}

/** The portfolio: every virtual account's balance as a cell of a stat strip, grouped, with its share of the total. */
export function AccountPortfolio({ accounts }: { accounts: AccountReport[] }) {
  const open = accounts.filter((a) => !a.archived);
  const total = open.reduce((s, a) => s + a.balance, 0);
  const positive = open.reduce((s, a) => s + Math.max(0, a.balance), 0);
  const pending = open.reduce((s, a) => s + a.pending, 0); // still with people, not in the balances yet
  const groups = (Object.keys(ACCOUNT_GROUPS) as AccountGroup[])
    .map((g) => ({ key: g, ...ACCOUNT_GROUPS[g], rows: open.filter((a) => a.group === g).sort((a, b) => b.balance - a.balance) }))
    .filter((g) => g.rows.length);
  const GROUP_ICON: Record<AccountGroup, [FinIconName, ArtName]> = { own: ["wallet", "accounts"], partner: ["globe", "partners"], other: ["layers", "other"] };
  const TONES: Tone[] = ["blue", "green", "violet", "amber", "orange", "navy"];

  return (
    <>
      <section className={`fport__head${total < 0 ? " fport__head--neg" : ""}`}>
        <span className="fport__heroicon"><Art art="accounts" icon="wallet" size={28} /></span>
        <div className="fport__herotext">
          <h2>Account portfolio</h2>
          <p>{num(open.length)} account{open.length === 1 ? "" : "s"} · {groups.length} group{groups.length === 1 ? "" : "s"}</p>
        </div>
        <div className="fport__total">
          <small>Total balance</small>
          <strong>{money(total)}</strong>
          {pending !== 0 && (
            <Link href="/finance/register" className="fport__pending">
              {pending > 0 ? `+ ${money(pending)} pending with people` : `− ${money(-pending)} owed back to people`}
            </Link>
          )}
        </div>
      </section>
      {groups.length === 0 && <p className="empty empty--big">No virtual accounts yet. Admins create them in Finance → Settings.</p>}
      {groups.map((g) => {
        const sum = g.rows.reduce((s, a) => s + a.balance, 0);
        return (
          <details key={g.key} className="fgroup" open>
            <summary>
              <span className={`fport__icon fport__icon--${g.key === "partner" ? "green" : g.key === "own" ? "blue" : "violet"}`}><Art icon={GROUP_ICON[g.key][0]} art={GROUP_ICON[g.key][1]} /></span>
              <span className="fgroup__title">
                <strong>{g.label} <span className="fcount">{g.rows.length}</span></strong>
                <small>{g.hint}</small>
              </span>
              <span className="fgroup__sum"><small>Balance</small><strong className={sum < 0 ? "neg" : undefined}>{money(sum)}</strong></span>
              <span className="fgroup__chev"><FinIcon name="chevronDown" size={18} /></span>
            </summary>
            <ul className="fstats">
              {g.rows.map((a, i) => (
                <StatCard
                  key={a.id}
                  tone={a.balance < 0 ? "red" : TONES[i % TONES.length]}
                  logo={accountLogoUrl(a.id, a.logo)}
                  label={a.name}
                  value={money(a.balance)}
                  caption={`${share(Math.max(0, a.balance), positive)} of portfolio`}
                  info={`${a.description ? `${a.description}. ` : ""}Opening balance ${money(a.opening)}. This month: +${money(a.income)} / −${money(a.expense)}${a.transferIn || a.transferOut ? `; transfers in ${money(a.transferIn)} / out ${money(a.transferOut)}` : ""}.${a.pending ? ` Pending, not in the balance yet: ${a.pending > 0 ? "+" : "−"}${money(Math.abs(a.pending))}.` : ""}`}
                  href={`/finance/transactions?account=${a.id}&period=month`}
                />
              ))}
            </ul>
          </details>
        );
      })}
    </>
  );
}
